pragma solidity ^0.8.19;

import "@aave/core-v3/contracts/interfaces/IPool.sol";
import "@connext/interfaces/IConnext.sol";

contract PrivateCrypMix {
    struct Commitment { bytes32 hash; bool used; uint256 timestamp; }
    mapping(bytes32 => Commitment) public commitments;
    IPool public immutable aavePool;
    IConnext public immutable connext;

    event Deposit(bytes32 indexed commitment, uint256 timestamp);
    event Withdrawal(address indexed recipient, uint256 amount);

    constructor(address _aave, address _connext) {
        aavePool = IPool(_aave);
        connext = IConnext(_connext);
    }

    function deposit(bytes32 _commitment) external payable {
        require(msg.value == 1 ether, "Invalid deposit size");
        aavePool.supply(address(0), msg.value, address(this), 0);
        commitments[_commitment] = Commitment(_commitment, false, block.timestamp);
        emit Deposit(_commitment, block.timestamp);
    }

